const SLOT_RANGES = [
  { start: 0, end: 5, primary: "cache-a", replica: "cache-b" },
  { start: 6, end: 11, primary: "cache-b", replica: "cache-a" },
  { start: 12, end: 15, primary: "cache-c", replica: "cache-a" }
];
const registry = {
  "cache-a": { state: "up" },
  "cache-b": { state: "up" },
  "cache-c": { state: "up" }
};
function hashKey(key) {
  return key.split("").reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7);
}
function route(key, localNode = "cache-b") {
  const keyHash = hashKey(key);
  const slot = keyHash % 16;
  const range = SLOT_RANGES.find(item => slot >= item.start && slot <= item.end);
  const target = registry[range.primary].state === "up" ? range.primary : range.replica;
  if (target !== localNode) {
    return { node: target, redirect: true, target, reason: "owner-mismatch" };
  }
  return { node: target, redirect: false, target };
}

